public void testSerializedViewCollection6() {
    servletContext.addInitParameter(MyfacesConfig.NUMBER_OF_VIEWS_IN_SESSION, "4");
    servletContext.addInitParameter(MyfacesConfig.NUMBER_OF_SEQUENTIAL_VIEWS_IN_SESSION, "2");
    SerializedViewCollection collection = new SerializedViewCollection();
    String viewId = "/test.xhtml";
    SerializedViewKey key1 = new SerializedViewKeyIntInt(viewId.hashCode(), 1);
    SerializedViewKey key2 = new SerializedViewKeyIntInt(viewId.hashCode(), 2);
    SerializedViewKey key3 = new SerializedViewKeyIntInt(viewId.hashCode(), 3);
    SerializedViewKey key4 = new SerializedViewKeyIntInt(viewId.hashCode(), 4);
    SerializedViewKey key5 = new SerializedViewKeyIntInt(viewId.hashCode(), 5);
    SerializedViewKey key6 = new SerializedViewKeyIntInt(viewId.hashCode(), 6);
    SerializedViewKey key7 = new SerializedViewKeyIntInt(viewId.hashCode(), 7);
    SerializedViewKey key8 = new SerializedViewKeyIntInt(viewId.hashCode(), 8);
    SerializedViewKey key9 = new SerializedViewKeyIntInt(viewId.hashCode(), 9);
    AtomicInteger destroyed = new AtomicInteger();
    collection.put(facesContext, new Object[] { null, null, 2 }, key1, null, "1", (id) -> destroyed.incrementAndGet());
    Assertions.assertNotNull(collection.get(key1));
    collection.put(facesContext, new Object[] { null, null, 2 }, key2, key1, "2", (id) -> destroyed.incrementAndGet());
    Assertions.assertNotNull(collection.get(key1));
    Assertions.assertNotNull(collection.get(key2));
    collection.put(facesContext, new Object[] { null, null, 2 }, key3, null, "3", (id) -> destroyed.incrementAndGet());
    Assertions.assertNotNull(collection.get(key1));
    Assertions.assertNotNull(collection.get(key2));
    Assertions.assertNotNull(collection.get(key3));
    collection.put(facesContext, new Object[] { null, null, 2 }, key4, key3, "4", (id) -> destroyed.incrementAndGet());
    Assertions.assertNotNull(collection.get(key1));
    Assertions.assertNotNull(collection.get(key2));
    Assertions.assertNotNull(collection.get(key3));
    Assertions.assertNotNull(collection.get(key4));
    collection.put(facesContext, new Object[] { null, null, 2 }, key2, null, "2", (id) -> destroyed.incrementAndGet());
    Assertions.assertNotNull(collection.get(key1));
    Assertions.assertNotNull(collection.get(key2));
    Assertions.assertNotNull(collection.get(key3));
    Assertions.assertNotNull(collection.get(key4));
    // The collection is full, but under a new key should remove key1
    collection.put(facesContext, new Object[] { null, null, 2 }, key5, null, "5", (id) -> destroyed.incrementAndGet());
    Assertions.assertNull(collection.get(key1));
    Assertions.assertNotNull(collection.get(key2));
    Assertions.assertNotNull(collection.get(key3));
    Assertions.assertNotNull(collection.get(key4));
    Assertions.assertNotNull(collection.get(key5));
    // The next oldest is key2, but it was refreshed, so the next one in age is key3
    collection.put(facesContext, new Object[] { null, null, 2 }, key6, null, "6", (id) -> destroyed.incrementAndGet());
    Assertions.assertNull(collection.get(key1));
    Assertions.assertNotNull(collection.get(key2));
    Assertions.assertNull(collection.get(key3));
    Assertions.assertNotNull(collection.get(key4));
    Assertions.assertNotNull(collection.get(key5));
    Assertions.assertNotNull(collection.get(key6));
    // There is a sequential view for key6, destroy the oldest one, which is key4
    collection.put(facesContext, new Object[] { null, null, 2 }, key7, key6, "7", (id) -> destroyed.incrementAndGet());
    Assertions.assertNull(collection.get(key1));
    Assertions.assertNotNull(collection.get(key2));
    Assertions.assertNull(collection.get(key3));
    Assertions.assertNull(collection.get(key4));
    Assertions.assertNotNull(collection.get(key5));
    Assertions.assertNotNull(collection.get(key6));
    Assertions.assertNotNull(collection.get(key7));
    // Since org.apache.myfaces.NUMBER_OF_SEQUENTIAL_VIEWS_IN_SESSION is 2, and we have
    // the sequence [key6, key7, key8] , the one to destroy is key6.
    collection.put(facesContext, new Object[] { null, null, 2 }, key8, key7, "8", (id) -> destroyed.incrementAndGet());
    Assertions.assertNull(collection.get(key1));
    Assertions.assertNotNull(collection.get(key2));
    Assertions.assertNull(collection.get(key3));
    Assertions.assertNull(collection.get(key4));
    Assertions.assertNotNull(collection.get(key5));
    Assertions.assertNull(collection.get(key6));
    Assertions.assertNotNull(collection.get(key7));
    Assertions.assertNotNull(collection.get(key8));
    // This is a sequence [key2, key9], but the oldest one is key2, so in this case
    // key2 should be removed.
    collection.put(facesContext, new Object[] { null, null, 2 }, key9, key2, "9", (id) -> destroyed.incrementAndGet());
    Assertions.assertNull(collection.get(key1));
    Assertions.assertNull(collection.get(key2));
    Assertions.assertNull(collection.get(key3));
    Assertions.assertNull(collection.get(key4));
    Assertions.assertNotNull(collection.get(key5));
    Assertions.assertNull(collection.get(key6));
    Assertions.assertNotNull(collection.get(key7));
    Assertions.assertNotNull(collection.get(key8));
    Assertions.assertNotNull(collection.get(key9));
    Assertions.assertEquals(destroyed.get(), 5);
}

@Test
public void testNumberOfSequentialViewsInSession() throws Exception {
    servletContext.addInitParameter(StateManager.STATE_SAVING_METHOD_PARAM_NAME, StateManager.STATE_SAVING_METHOD_SERVER);
    servletContext.addInitParameter("org.apache.myfaces.NUMBER_OF_VIEWS_IN_SESSION", "5");
    servletContext.addInitParameter("org.apache.myfaces.NUMBER_OF_SEQUENTIAL_VIEWS_IN_SESSION", "2");
    servletContext.addInitParameter(StateManager.SERIALIZE_SERVER_STATE_PARAM_NAME, "true");
    // Initialization
    setupRequest();
    StateCache stateCache = new StateCacheServerSide();
    tearDownRequest();
    Object savedToken;
    Object firstSavedToken;
    try {
        setupRequest();
        facesContext.getViewRoot().setViewId("view1.xhtml");
        savedToken = stateCache.saveSerializedView(facesContext, 1);
        firstSavedToken = savedToken;
    } finally {
        tearDownRequest();
    }
    try {
        setupRequest();
        Object value = stateCache.restoreSerializedView(facesContext, "view1.xhtml", savedToken);
        Assertions.assertEquals(1, value);
        facesContext.getViewRoot().setViewId("view2.xhtml");
        savedToken = stateCache.saveSerializedView(facesContext, 2);
    } finally {
        tearDownRequest();
    }
    try {
        setupRequest();
        Object value = stateCache.restoreSerializedView(facesContext, "view2.xhtml", savedToken);
        Assertions.assertEquals(2, value);
        facesContext.getViewRoot().setViewId("view2.xhtml");
        savedToken = stateCache.saveSerializedView(facesContext, 3);
    } finally {
        tearDownRequest();
    }
    try {
        setupRequest();
        Object value = stateCache.restoreSerializedView(facesContext, "view1.xhtml", firstSavedToken);
        // Since org.apache.myfaces.NUMBER_OF_SEQUENTIAL_VIEWS_IN_SESSION is 2, the first one was already discarded
        Assertions.assertNull(value);
    } finally {
        tearDownRequest();
    }
}

@Test
public void testSaveRestoreStateWrongViewId() throws Exception {
    servletContext.addInitParameter(StateManager.STATE_SAVING_METHOD_PARAM_NAME, StateManager.STATE_SAVING_METHOD_SERVER);
    // Initialization
    setupRequest();
    StateCache stateCache = new StateCacheClientSide();
    tearDownRequest();
    Object savedToken;
    Object firstSavedToken;
    try {
        setupRequest();
        facesContext.getViewRoot().setViewId("/view1.xhtml");
        savedToken = stateCache.saveSerializedView(facesContext, 1);
        firstSavedToken = savedToken;
    } finally {
        tearDownRequest();
    }
    try {
        setupRequest();
        // Note we are trying to restore restoring another different view with a token from the previous view.
        // It should return null and later throw ViewExpiredException
        // In server side state saving, the hashCode of the viewId should be part of the key used to restore
        // the state, along with a counter.
        Object value = stateCache.restoreSerializedView(facesContext, "/view2.xhtml", firstSavedToken);
        Assertions.assertNull(value);
    } finally {
        tearDownRequest();
    }
    try {
        setupRequest();
        // It should restore this:
        Object value = stateCache.restoreSerializedView(facesContext, "/view1.xhtml", firstSavedToken);
        Assertions.assertEquals(1, value);
    } finally {
        tearDownRequest();
    }
}

