/**
 * This test tests if it is possible to render HTML elements inside
 * a script section without confusing the HtmlResponseWriterImpl.
 * The related issue to this test is MYFACES-2668.
 *
 * @throws IOException
 * @throws NoSuchFieldException
 * @throws SecurityException
 * @throws IllegalAccessException
 * @throws IllegalArgumentException
 */
@Test
public void testHtmlElementsInsideScript() throws IOException, SecurityException, NoSuchFieldException, IllegalArgumentException, IllegalAccessException {
    // use reflection to get the field _isInsideScript to verify
    // the internal behavior of HtmlResponseWriterImpl
    Field insideScriptField = _writer.getClass().getDeclaredField("_isInsideScript");
    insideScriptField.setAccessible(true);
    _writer.startDocument();
    _writer.startElement("head", null);
    Assertions.assertFalse(getFieldBooleanValue(insideScriptField, _writer, false), "We have not entered a script element yet, so _isInsideScript should be false (or null).");
    _writer.startElement("script", null);
    Assertions.assertTrue(getFieldBooleanValue(insideScriptField, _writer, false), "We have now entered a script element, so _isInsideScript should be true.");
    _writer.startElement("table", null);
    _writer.startElement("tr", null);
    _writer.startElement("td", null);
    Assertions.assertTrue(getFieldBooleanValue(insideScriptField, _writer, false), "We have now opened various elements inside a script element, " + "but _isInsideScript should still be true.");
    _writer.write("column value");
    Assertions.assertTrue(getFieldBooleanValue(insideScriptField, _writer, false), "We have now written some text inside a script element, " + "but _isInsideScript should still be true.");
    _writer.endElement("td");
    _writer.endElement("tr");
    _writer.endElement("table");
    _writer.endElement("script");
    Assertions.assertFalse(getFieldBooleanValue(insideScriptField, _writer, false), "We have now closed the script element, so _isInsideScript should be " + "false (or null).");
    _writer.endElement("head");
    _writer.endDocument();
    String output = _stringWriter.toString();
    Assertions.assertTrue(output.contains(COMMENT_START), "A script start was rendered, so the output has to " + "contain " + COMMENT_START);
    Assertions.assertTrue(output.contains(COMMENT_END), "A script end was rendered so the output has to " + "contain " + COMMENT_END);
}

