    Assert.assertTrue(webDriver.getPageSource().contains("ViewState"));
    // check if bar.xml is served as non-exact-mapping
    Assert.assertTrue(webDriver.getCurrentUrl().endsWith("/bar.jsf") || webDriver.getCurrentUrl().endsWith("/faces/bar") || webDriver.getCurrentUrl().endsWith("/faces/bar.xhtml"));
}

